parameters.jsCode:
const raw = $input.first().json.content[0].text;
let notes;
try {
  notes = JSON.parse(raw);
} catch (e) {
  const m = raw.match(/\{[\s\S]*\}/);
  try { notes = JSON.parse(m[0]); } catch { notes = { executive_summary: raw.substring(0, 300), key_topics: [], decisions_made: [], action_items: [], open_questions: [], next_meeting_agenda: [], full_notes_markdown: raw, follow_up_email: {subject: 'Meeting Notes', body: raw.substring(0, 500)} }; }
}
const meeting = $('Extract Meeting Data').first().json;
return [{ json: { ...notes, meeting_title: meeting.meeting_title, date: meeting.date, attendees: meeting.attendees, duration_mins: meeting.duration_mins, generated_at: new Date().toISOString() } }];

